## SQL setup (run once in Supabase)
```sql
create extension if not exists vector with schema extensions;

create table if not exists public.rag_documents (
  id uuid primary key default gen_random_uuid(),
  text text,
  metadata jsonb,
  embedding extensions.vector
);
create index if not exists rag_documents_file_id_idx
  on public.rag_documents ((metadata->>'file_id'));

create table if not exists public.rag_message_log (
  id bigserial primary key,
  chat_id bigint not null,
  user_id bigint,
  level int,
  message text,
  created_at timestamptz not null default now()
);
create index if not exists rag_message_log_chat_time_idx
  on public.rag_message_log (chat_id, created_at desc);

alter table public.rag_documents enable row level security;
alter table public.rag_message_log enable row level security;
```
The chat memory table (rag_chat_memory) is created automatically.

### Remove a deleted document
```sql
delete from public.rag_documents
  where metadata->>'file_name' = 'Old price list.pdf';
```

### Optional: daily log cleanup
```sql
create extension if not exists pg_cron;
select cron.schedule('rag-log-cleanup', '0 3 * * *',
  $$delete from public.rag_message_log
    where created_at < now() - interval '30 days'$$);
```

