// Classify each message WITHOUT an LLM (instant and free)
// level -1 = not text (photo without caption, voice, sticker)
// level 0  = greeting, thanks or emoji only -> canned reply
// level 1  = real question -> AI agent with RAG
// level 2  = complaint or asks for a human -> hand off to admin
// Photo captions count as text. Adjust the keyword lists and replies to your customers' language.
const msg = $('When Telegram Message Received').first().json.message;
const raw = String(msg?.text ?? msg?.caption ?? '').trim();
const isText = raw.length > 0;
const t = raw.toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, ' ').replace(/\s+/g, ' ').trim();

const greetingOnly = /^(hi|hello|hey|good (morning|afternoon|evening)|start)( there)?$/;
const thanksOnly = /^(thanks|thank you|thx|ok|okay|great|cool)( (so much|a lot))?$/;
const handoff = /\b(complaint|refund not received|talk to (a )?(human|person|admin|agent)|contact admin|speak to (a )?(human|person|admin)|my order (has not|hasn t|didn t) arrived|scam)\b/;

let level = isText ? 1 : -1;
let reply = '';

if (!isText) {
  // handled by the If Text Message node
} else if (handoff.test(t)) {
  level = 2;
  reply = 'Sorry about that 🙏 I\'ve passed your message to our team, and someone will get back to you soon.';
} else if (t === '') {
  // Emoji only: a wave is a greeting, anything else (thumbs up, heart, ok hand) is an acknowledgement
  level = 0;
  reply = /\u{1F44B}/u.test(raw)
    ? 'Hi! 😊 What can I help you with today?'
    : 'Glad I could help! 😊';
} else if (greetingOnly.test(t)) {
  level = 0;
  reply = 'Hi! 😊 What can I help you with today?';
} else if (thanksOnly.test(t)) {
  level = 0;
  reply = 'Anytime! Just message me if anything else comes up.';
}

return [{
  json: {
    level,
    isText,
    query: isText ? raw : '[non-text message]',
    reply,
    chatId: msg.chat.id,
    userId: msg.from?.id ?? msg.chat.id,
    name: [msg.from?.first_name, msg.from?.last_name].filter(Boolean).join(' ') || 'Customer',
    username: msg.from?.username ?? ''
  }
}];

