// Telegram rejects messages over 4096 characters.
// Strip markdown and lines that start with "Source:", split into messages of max 2500 characters,
// then escape &, < and > because Send Prepared Answer uses HTML parse mode.
const LIMIT = 2500;
const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
let text = String($input.first().json.output || '').trim();

text = text
  .replace(/^\s*(source|sources|sumber)\s*:.*$/gim, '')
  .replace(/\*\*(.+?)\*\*/g, '$1')
  .replace(/__(.+?)__/g, '$1')
  .replace(/^#{1,6}\s*/gm, '')
  .replace(/^\s*-{3,}\s*$/gm, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

const chunks = [];
let current = '';
const push = (piece, sep) => {
  if (!current) { current = piece; return; }
  if ((current + sep + piece).length <= LIMIT) { current += sep + piece; return; }
  chunks.push(current);
  current = piece;
};

for (const para of text.split(/\n{2,}/)) {
  if (para.length <= LIMIT) { push(para, '\n\n'); continue; }
  for (const line of para.split('\n')) {
    let part = line;
    while (part.length > LIMIT) {
      if (current) { chunks.push(current); current = ''; }
      let cut = part.lastIndexOf(' ', LIMIT);
      if (cut < LIMIT * 0.5) cut = LIMIT;
      chunks.push(part.slice(0, cut).trim());
      part = part.slice(cut).trim();
    }
    if (part) push(part, '\n');
  }
}
if (current) chunks.push(current);
if (chunks.length === 0) chunks.push('Sorry, I could not answer that. Please try again.');

return chunks.map((c, i) => ({
  json: { output: esc(chunks.length > 1 ? c + '\n\n(' + (i + 1) + '/' + chunks.length + ')' : c) },
  pairedItem: { item: 0 }
}));

